template.solver:
def solve(M):
    c0 = M // 3
    c1 = (M + 2) // 3
    c2 = (M + 1) // 3
    for N in range(M, 0, -1):
        if N % 2 == 1:
            if N <= c0:
                return N
            continue
        k = N // 2
        ok = False
        if N <= c0:
            ok = True
        if k % 2 == 0 and c0 >= k and c1 >= k // 2 and c2 >= k // 2:
            ok = True
        if k % 2 == 0 and c1 >= k and c2 >= k:
            ok = True
        if ok:
            return N
    return 0
